import {controller, target} from '@github/catalyst'
import type {CacheHitSource} from '@github-ui/relay-query-cache/create-query-cache'
import {SOFT_NAV_STATE} from '@github-ui/soft-nav/states'
import {inSoftNav} from '@github-ui/soft-nav/utils'

/**
 * Custom element for displaying relay query cache hit indicator in the staff bar.
 *
 * Shows a cache icon when the current navigation used cached data.
 * For IndexedDB and hot cache hits, only tracks during soft navigation (not on initial hard page load).
 * For service worker cache hits, always shows the indicator since the SW did meaningful work
 * to inject the cached payload (even on hard navigation).
 *
 * Listens for:
 * - 'relay-cache-hit': Shows indicator when cache data is used for rendering
 * - 'soft-nav:start': Enables tracking and hides indicator for new soft navigation
 * - 'soft-nav:end': Disables tracking (cache hits after navigation completes don't count)
 *
 * Note: IndexedDB/hot cache hits that occur before any soft-nav:start (e.g., on hard refresh) are
 * intentionally ignored since they're not part of a navigation leveraging the cache.
 *
 * For turbo navigations across different pages (e.g., PR → Issue), the soft-nav:start
 * event fires on the old page before navigation. When this element connects on the new
 * page, we check session storage via inSoftNav() to detect if a soft navigation is
 * already in progress, ensuring we capture cache hits during turbo cache navigations.
 */

const TOOLTIP_TEXT: Record<CacheHitSource, string> = {
  'indexed-db': 'This navigation used cached data',
  'hot-cache': 'This navigation used cached data (hot cache)',
  'service-worker': 'This navigation used cached data (service worker)',
}

@controller('relay-cache-staffbar')
class RelayCacheStaffbarElement extends HTMLElement {
  @target declare indicator: HTMLElement

  #isTrackingEnabled = false

  connectedCallback() {
    // relay-cache-hit is dispatched on window, not document
    window.addEventListener('relay-cache-hit', this.handleCacheHit)
    document.addEventListener(SOFT_NAV_STATE.START, this.startTracking)
    document.addEventListener(SOFT_NAV_STATE.END, this.stopTracking)

    // For turbo navigations, soft-nav:start fires on the old page before this element
    // connects on the new page. Check session storage to see if a soft nav is in progress.
    if (inSoftNav()) {
      this.#isTrackingEnabled = true
    }
  }

  disconnectedCallback() {
    window.removeEventListener('relay-cache-hit', this.handleCacheHit)
    document.removeEventListener(SOFT_NAV_STATE.START, this.startTracking)
    document.removeEventListener(SOFT_NAV_STATE.END, this.stopTracking)
  }

  handleCacheHit = (event: Event) => {
    const source = (event as CustomEvent<{source?: CacheHitSource}>).detail?.source ?? 'indexed-db'
    if (source === 'service-worker') {
      this.show(source)
      return
    }
    // For other cache sources, only show indicator during an active soft navigation
    if (!this.#isTrackingEnabled) return
    this.show(source)
  }

  startTracking = () => {
    // Enable tracking and hide indicator at the start of a soft navigation
    this.#isTrackingEnabled = true
    this.hide()
  }

  stopTracking = () => {
    // Disable tracking after soft navigation completes
    this.#isTrackingEnabled = false
  }

  show = (source: CacheHitSource = 'indexed-db') => {
    if (this.indicator) {
      this.indicator.hidden = false
    }

    const tooltip = this.querySelector('tool-tip[for="relay-cache-staffbar-indicator"]')
    if (tooltip) {
      tooltip.textContent = TOOLTIP_TEXT[source] ?? null
    }
  }

  hide = () => {
    if (this.indicator) {
      this.indicator.hidden = true
    }
  }
}
